    let post_res = post_residual as f64;

    // Base score: prioritize minimizing remaining space (Best Fit)
    let mut score = post_res;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We penalize exponentially as post_residual approaches the minimum item size threshold (~10).
    if post_res > 0.0 && post_res < 10.0 {
        score += (10.0 - post_res).powf(2.5);
