        score -= 5.0 * progress;
    }

    // New Bin Logic: If this is an empty bin call, calibrate the cost of starting a new bin.
    // The cost scales with progress to prevent fragmentation late in the stream.
    if bin_residual == bin_capacity {
        score = 25.0 + (10.0 * progress);
    } else {
        // Penalty for bins that deviate significantly from the mean residual
        // to encourage uniform fill levels across all open bins.
        score += (post_res - mean_residual).abs() * 0.5;
