        // Only open a new bin if the average residual of existing bins is already very low,
        // suggesting that current bins are too full to accommodate future items.
        if mean_residual > 15.0 {
            score += 25.0;
        } else {
            score += 60.0; // Strong penalty for opening new bins unnecessarily early
        }
